(function () {
  var baseurl = window.SITE.baseurl || "";
  var YEARS = window.SITE.years.map(String);

  // Parcel shapes keyed by "CPL Property Address", generated by scripts/match_parcels.py
  var PARCELS_URL = baseurl + "/data/parcels.geojson";

  // Address -> [lng, lat] lookup, generated by scripts/geocode.py
  var GEOCODED_URL = baseurl + "/data/geocoded.csv";

  var COL = OPData.COL;
  var isReported = OPData.isReported;

  // Total GHG emissions (t CO2e), sequential blue (light = low, dark = high).
  // Breaks match the GHG filter ranges. Only reporting buildings are colored.
  var FILL_COLOR = [
    "step", ["get", "ghgValue"],
    "#9ec5f4", 50,
    "#5598e7", 100,
    "#2a78d6", 250,
    "#1c5cab", 500,
    "#0d366b"
  ];
  var MISSING_STROKE = "#7a7974";

  var select = OPData.yearPicker("year-select");
  var filterSelects = Array.prototype.slice.call(document.querySelectorAll("select.filter"));
  var filterHint = document.getElementById("filter-hint");
  var statusEl = document.getElementById("map-status");
  var statEl = document.getElementById("compliance-stat");
  var chartEl = document.getElementById("compliance-chart");
  var tableBody = document.querySelector("#compliance-table tbody");

  var rowsByYear = {};  // { year: [csv rows] }
  var parcels = null;   // GeoJSON FeatureCollection, if available
  var geocoded = {};    // { address: [lng, lat] }

  // ---------- helpers ----------

  function num(v) {
    var n = parseFloat(v);
    return isNaN(n) ? null : n;
  }

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  function fmt(n) { return n.toLocaleString("en-US"); }

  function parseCSV(url) {
    return new Promise(function (resolve) {
      Papa.parse(url, {
        download: true, header: true, skipEmptyLines: true,
        complete: function (r) { resolve(r.data); },
        error: function () { resolve([]); }
      });
    });
  }

  // ---------- data ----------

  function loadAll() {
    var years = OPData.loadYears(baseurl, YEARS).then(function (byYear) { rowsByYear = byYear; });
    var geo = parseCSV(GEOCODED_URL).then(function (rows) {
      rows.forEach(function (r) {
        var lat = num(r.latitude), lng = num(r.longitude);
        if (lat !== null && lng !== null) geocoded[r.address] = [lng, lat];
      });
    });
    var parcelReq = fetch(PARCELS_URL)
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) { parcels = d; })
      .catch(function () { parcels = null; });
    return Promise.all([years, geo, parcelReq]);
  }

  // Floor area for the size chart: the Cook County Assessor's building area when
  // there is one; otherwise (mostly tax-exempt property) the self-reported value
  // for that year, else the same building's value from the nearest other year.
  var gfaById = {}; // { featureId: { year: self-reported gfa } }

  function indexFloorArea() {
    YEARS.forEach(function (y) {
      (rowsByYear[y] || []).forEach(function (r) {
        var g = num(r[COL.gfa]);
        if (g === null) return;
        (gfaById[r[COL.id]] = gfaById[r[COL.id]] || {})[y] = g;
      });
    });
  }

  function floorArea(row, year) {
    if (row._assessor_sf) return row._assessor_sf;
    var own = num(row[COL.gfa]);
    if (own !== null) return own;
    var byYear = gfaById[row[COL.id]];
    if (!byYear) return null;
    var best = null, bestDist = Infinity;
    Object.keys(byYear).forEach(function (y) {
      var d = Math.abs(Number(y) - Number(year));
      if (d < bestDist || (d === bestDist && y > best)) { best = y; bestDist = d; }
    });
    return byYear[best];
  }

  var SIZE_BINS = [
    { label: "Under 10,000 ft²", min: 0, max: 10000 },
    { label: "10,000–24,999 ft²", min: 10000, max: 25000 },
    { label: "25,000–49,999 ft²", min: 25000, max: 50000 },
    { label: "50,000–99,999 ft²", min: 50000, max: 100000 },
    { label: "100,000 ft² and up", min: 100000, max: Infinity },
    { label: "Size unknown", unknown: true }
  ];

  function complianceBySize(year) {
    var bins = SIZE_BINS.map(function (b) { return { label: b.label, bin: b, reported: 0, missing: 0 }; });
    (rowsByYear[year] || []).forEach(function (r) {
      var g = floorArea(r, year);
      var bin = bins.filter(function (b) {
        return g === null ? b.bin.unknown : (!b.bin.unknown && g >= b.bin.min && g < b.bin.max);
      })[0];
      if (isReported(r)) bin.reported++; else bin.missing++;
    });
    bins.forEach(function (b) { b.total = b.reported + b.missing; });
    return bins.filter(function (b) { return b.total > 0; });
  }

  function compliance(year) {
    var rows = rowsByYear[year] || [];
    var reported = rows.filter(isReported).length;
    return { year: year, total: rows.length, reported: reported, missing: rows.length - reported };
  }

  // ---------- map ----------

  var map = new maplibregl.Map({
    container: "map",
    style: "https://basemaps.cartocdn.com/gl/positron-gl-style/style.json",
    center: [-87.7845, 41.8850],
    zoom: 13.5
  });
  map.addControl(new maplibregl.NavigationControl(), "top-right");

  function properties(row) {
    var score = num(row[COL.score]);
    return {
      id: row[COL.id],
      name: row[COL.name] || "",
      address: row[COL.address] || "",
      type: row[COL.type] || "",
      gfa: row[COL.gfa] || "",
      eui: row[COL.eui] || "",
      ghg: row[COL.ghg] || "",
      ghgValue: num(row[COL.ghg]) || 0,
      score: score === null ? -1 : score,
      reported: isReported(row),
      listed: row._listed !== false,
      unlisted: !!row._unlisted,
      assessorSf: row._assessor_sf || 0,
      assessorDesc: row._assessor_desc || ""
    };
  }

  // Parcel polygon when one matches the address, otherwise the geocoded point.
  function toGeoJSON(rows) {
    var parcelIndex = {};
    if (parcels) {
      parcels.features.forEach(function (f) {
        parcelIndex[f.properties.address] = f.geometry;
      });
    }
    var features = [];
    rows.forEach(function (row) {
      var address = (row[COL.address] || "").trim();
      var geom = row._geometry || parcelIndex[address];
      if (!geom) {
        var coords = geocoded[address];
        if (coords) geom = { type: "Point", coordinates: coords };
      }
      if (geom) features.push({ type: "Feature", geometry: geom, properties: properties(row) });
    });
    return { type: "FeatureCollection", features: features };
  }

  function popupHTML(p) {
    var title = esc(p.name || p.address || "Property");
    if (p.unlisted) {
      return '<div class="popup"><h3>' + title + "</h3>" +
        "<p><em>Not on the Village's benchmarking list.</em> The Cook County Assessor puts this " +
        "building at " + fmt(p.assessorSf) + " ft², over the 10,000 ft² threshold.</p>" +
        (p.assessorDesc ? '<p class="muted">' + esc(p.assessorDesc) + "</p>" : "") + "</div>";
    }
    if (!p.reported) {
      return '<div class="popup"><h3>' + title + "</h3><p>" + esc(p.address) +
        "</p><p><em>Did not report this year" +
        (p.listed ? "" : " (missing from this year's benchmarking list)") + ".</em></p></div>";
    }
    var fields = [
      ["Address", p.address],
      ["Type", p.type],
      ["Floor area (ft²)", p.gfa],
      ["Site EUI (kBtu/ft²)", p.eui],
      ["ENERGY STAR score", p.score >= 0 ? p.score : ""],
      ["GHG (t CO2e)", p.ghg]
    ];
    var rows = fields.map(function (f) {
      return "<tr><td>" + f[0] + "</td><td>" + (f[1] !== "" ? esc(f[1]) : "&mdash;") + "</td></tr>";
    }).join("");
    return '<div class="popup"><h3>' + title + "</h3><table>" + rows + "</table></div>";
  }

  var POLYGON = ["in", ["geometry-type"], ["literal", ["Polygon", "MultiPolygon"]]];
  var POINT = ["==", ["geometry-type"], "Point"];

  function addLayers() {
    map.addSource("buildings", { type: "geojson", data: { type: "FeatureCollection", features: [] } });

    map.addLayer({
      id: "buildings-fill", type: "fill", source: "buildings", filter: POLYGON,
      paint: {
        "fill-color": ["case", ["get", "reported"], FILL_COLOR, "#ffffff"],
        "fill-opacity": ["case", ["get", "reported"], 0.8, 0.4]
      }
    });
    map.addLayer({
      id: "buildings-outline", type: "line", source: "buildings", filter: POLYGON,
      paint: {
        "line-color": ["case", ["get", "reported"], "#333333", MISSING_STROKE],
        "line-width": ["case", ["get", "reported"], 0.5, 1.5]
      }
    });
    map.addLayer({
      id: "buildings-points", type: "circle", source: "buildings", filter: POINT,
      layout: { "circle-sort-key": ["case", ["get", "reported"], 1, 0] },
      paint: {
        "circle-radius": 6,
        "circle-color": ["case", ["get", "reported"], FILL_COLOR, "#ffffff"],
        "circle-stroke-color": ["case", ["get", "reported"], "#333333", MISSING_STROKE],
        "circle-stroke-width": ["case", ["get", "reported"], 1, 2]
      }
    });

    ["buildings-fill", "buildings-points"].forEach(function (layer) {
      map.on("click", layer, function (e) {
        new maplibregl.Popup().setLngLat(e.lngLat).setHTML(popupHTML(e.features[0].properties)).addTo(map);
      });
      map.on("mouseenter", layer, function () { map.getCanvas().style.cursor = "pointer"; });
      map.on("mouseleave", layer, function () { map.getCanvas().style.cursor = ""; });
    });
  }

  // ---------- compliance chart ----------

  var SVG_NS = "http://www.w3.org/2000/svg";
  function makeTooltip(container) {
    var tip = document.createElement("div");
    tip.className = "tooltip";
    tip.hidden = true;
    container.appendChild(tip);
    return {
      el: tip,
      show: function (e, html) {
        var box = container.getBoundingClientRect();
        tip.innerHTML = html;
        tip.hidden = false;
        var left = Math.min(e.clientX - box.left + 12, box.width - tip.offsetWidth);
        tip.style.left = Math.max(0, left) + "px";
        tip.style.top = (e.clientY - box.top - tip.offsetHeight - 8) + "px";
      },
      hide: function () { tip.hidden = true; }
    };
  }

  var tooltip = makeTooltip(chartEl);

  function el(name, attrs, text) {
    var node = document.createElementNS(SVG_NS, name);
    Object.keys(attrs).forEach(function (k) { node.setAttribute(k, attrs[k]); });
    if (text !== undefined) node.textContent = text;
    return node;
  }

  // One chart: an "All buildings" bar for the selected year, then one bar per
  // floor-area range, all on the same count scale (the ranges sum to the top bar).
  // Each bar is reported vs. did not report.
  function renderChart(year) {
    var c = compliance(year);
    var overall = { label: "All buildings", reported: c.reported, missing: c.missing, total: c.total, overall: true };
    var bins = complianceBySize(year);
    var data = [overall].concat(bins);

    var rowH = 22, rowGap = 10, sectionGap = 14, labelW = 128, rateW = 40;
    var W = 400, H = data.length * (rowH + rowGap) - rowGap + sectionGap + 4;
    var pw = W - labelW - rateW, GAP = 2;

    var old = chartEl.querySelector("svg");
    if (old) old.remove();
    var svg = el("svg", { viewBox: "0 0 " + W + " " + H, "aria-hidden": "true" });

    data.forEach(function (d, i) {
      var y = i * (rowH + rowGap) + 2 + (i > 0 ? sectionGap : 0), cy = y + rowH / 2 + 4;
      var rate = d.total ? Math.round(100 * d.reported / d.total) : 0;
      var g = el("g", { "class": "size-row" });
      g.appendChild(el("rect", { x: 0, y: y - rowGap / 2, width: W, height: rowH + rowGap, fill: "transparent" }));
      g.appendChild(el("text", { x: 0, y: cy, "font-size": 12,
        fill: d.overall ? "var(--text-primary)" : "var(--text-secondary)",
        "font-weight": d.overall ? 600 : 400 }, d.label));

      var x0 = labelW;
      var wRep = c.total ? (d.reported / c.total) * pw : 0;
      var wMis = c.total ? (d.missing / c.total) * pw : 0;
      if (d.reported) {
        g.appendChild(el("rect", { "class": "bar", x: x0, y: y, width: wRep, height: rowH, fill: "var(--reported)" }));
        if (wRep > 26) {
          g.appendChild(el("text", { x: x0 + 6, y: cy, "font-size": 11, fill: "#ffffff", "font-weight": 600 }, fmt(d.reported)));
        }
      }
      if (d.missing) {
        var xm = x0 + wRep + (d.reported ? GAP : 0);
        var w = Math.max(1, wMis - (d.reported ? GAP : 0));
        // round the data end (right side) only
        var r = Math.min(4, w / 2, rowH / 2);
        g.appendChild(el("path", { "class": "bar", fill: "var(--missing)",
          d: "M" + xm + "," + y + "H" + (xm + w - r) + "Q" + (xm + w) + "," + y + " " + (xm + w) + "," + (y + r) +
             "V" + (y + rowH - r) + "Q" + (xm + w) + "," + (y + rowH) + " " + (xm + w - r) + "," + (y + rowH) +
             "H" + xm + "Z" }));
      }
      g.appendChild(el("text", { x: W, y: cy, "text-anchor": "end", "font-size": 11,
        fill: "var(--text-primary)", "font-weight": d.overall ? 600 : 400 }, rate + "%"));

      g.addEventListener("mousemove", function (e) {
        tooltip.show(e, "<strong>" + d.label + "</strong> · " + rate + "% reported<br>" +
          fmt(d.reported) + ' <span class="muted">reported</span> · ' +
          fmt(d.missing) + ' <span class="muted">did not</span>');
      });
      g.addEventListener("mouseleave", tooltip.hide);
      svg.appendChild(g);

      if (d.overall) {
        var ly = y + rowH + rowGap / 2 + sectionGap / 2;
        svg.appendChild(el("line", { x1: 0, x2: W, y1: ly, y2: ly, stroke: "var(--border)", "stroke-width": 1 }));
      }
    });

    chartEl.insertBefore(svg, tooltip.el);

    tableBody.innerHTML = data.map(function (d) {
      var cell = d.overall ? "th" : "td";
      return "<tr><" + cell + ">" + d.label + "</" + cell + "><td>" + fmt(d.reported) + "</td><td>" +
        fmt(d.missing) + "</td><td>" + (d.total ? Math.round(100 * d.reported / d.total) : 0) + "%</td></tr>";
    }).join("");

    statEl.innerHTML = "<strong>" + (c.total ? Math.round(100 * c.reported / c.total) : 0) +
      "%</strong> of covered buildings reported in " + year + " (" +
      fmt(c.reported) + " of " + fmt(c.total) + ")";

    document.getElementById("size-chart-hint").textContent = "Floor area is the Cook County " +
      "Assessor's building area; buildings without one (mostly tax-exempt) use their self-reported " +
      "floor area. \u201cSize unknown\u201d buildings have neither.";
  }

  // ---------- filters ----------

  // Each filter <select> has data-col (a CSV column), or data-size for floor
  // area (the same Assessor-first sizing as the size chart). Option values are
  // "min-max" (max may be blank, upper bound exclusive), "none" (value missing),
  // or "" (no filter). Buildings that didn't report have no emissions data,
  // so they never match that filter; they can match the floor-area filter.
  function activeFilters() {
    return filterSelects.filter(function (s) { return s.value; }).map(function (s) {
      var f = { col: s.dataset.col, size: !!s.dataset.size };
      if (s.value === "none") { f.none = true; return f; }
      var parts = s.value.split("-");
      f.min = num(parts[0]) || 0;
      f.max = num(parts[1]);
      return f;
    });
  }

  function matches(row, filters, year) {
    var needsReport = filters.some(function (f) { return !f.size; });
    if (needsReport && !isReported(row)) return false;
    return filters.every(function (f) {
      var v = f.size ? floorArea(row, year) : num(row[f.col]);
      if (f.none) return v === null;
      return v !== null && v >= f.min && (f.max === null || v < f.max);
    });
  }

  function updateMap() {
    var year = select.value, filters = activeFilters();
    var rows = (rowsByYear[year] || []).filter(function (r) { return matches(r, filters, year); });
    var geojson = toGeoJSON(rows);
    if (map.getSource("buildings")) map.getSource("buildings").setData(geojson);
    filterHint.hidden = !filters.length;
    document.getElementById("filter-hint-text").hidden =
      !filters.some(function (f) { return !f.size; });
    var unmapped = rows.length - geojson.features.length;
    statusEl.textContent = "Showing " + fmt(geojson.features.length) + " buildings" +
      (filters.length ? " matching the filters" : "") + "." +
      (unmapped ? " " + fmt(unmapped) + " more have addresses that couldn't be located." : "");
  }

  function setYear(year) {
    select.value = year;
    renderChart(year);
    updateMap();
  }

  select.addEventListener("change", function () { setYear(select.value); });
  filterSelects.forEach(function (s) { s.addEventListener("change", updateMap); });
  document.getElementById("clear-filters").addEventListener("click", function () {
    filterSelects.forEach(function (s) { s.value = ""; });
    updateMap();
  });

  var mapReady = new Promise(function (resolve) { map.on("load", function () { addLayers(); resolve(); }); });
  var dataReady = loadAll();
  dataReady.then(function () { indexFloorArea(); renderChart(select.value); });
  Promise.all([mapReady, dataReady]).then(function () { setYear(select.value); });
})();
